changeSet.sql:
ALTER TABLE connection ADD CONSTRAINT ck_outline_connection_origin
    CHECK (kind <> 'OUTLINE' OR outline_origin IS NOT NULL
        OR (state <> 'ACTIVE' AND config->>'serverUrl' IS NULL));
ALTER TABLE identity_provider ADD CONSTRAINT ck_outline_identity_origin
    CHECK (type <> 'OUTLINE' OR outline_origin IS NOT NULL);
